/// <summary>
/// CB 797 send PE pricing Data contract class for service <c>METPriceComponentContract</c>
/// </summary>
[DataContractAttribute]
public class METPriceComponentContract
{

    InventTransId            inventTransId;
    METPriceCodeRef          priceCodeRef;
    METComponent             component,defComponent;
    Amount                   amountValue;
    private List             priceComponentDetailArray;


}

Method.Source:
/// <summary>
/// Parameter method for InventTransId
/// </summary>
/// <param name = "_inventTransId">InventTransId</param>
/// <returns>InventTransId</returns>
[DataMemberAttribute('InventTransId')]
public InventTransId parmInventTransId(InventTransId _inventTransId = inventTransId)
{
    inventTransId  = _inventTransId;
    return inventTransId;
}

/// <summary>
/// Parameter method for priceCodeRef
/// </summary>
/// <param name = "_codeRef">priceCodeRef</param>
/// <returns>priceCodeRef</returns>
[DataMemberAttribute('priceCodeRef')]
public METPriceCodeRef parmPriceCodeRef(METPriceCodeRef _codeRef = priceCodeRef)
{
    priceCodeRef  = _codeRef;
    return priceCodeRef;
}

/// <summary>
/// Parameter method for component
/// </summary>
/// <param name = "_component">component</param>
/// <returns>Component</returns>
[DataMemberAttribute('component')]
public METComponent parmComponent(METComponent _component = component)
{
    component  = _component;
    return component;
}

/// <summary>
/// Parameter method for defComponent
/// </summary>
/// <param name = "_defcomponent">defcomponent</param>
/// <returns>Component</returns>
[DataMemberAttribute('defComponent')]
public METComponent parmDefComponent(METComponent _defcomponent = component)
{
    component  = _defcomponent;
    return component;
}

/// <summary>
/// Parameter method for amountValue
/// </summary>
/// <param name = "_amountValue">Amount</param>
/// <returns>Amount</returns>
[DataMemberAttribute('amountValue')]
public Amount parmAmountValue(Amount _amountValue = amountValue)
{
    amountValue  = _amountValue;
    return amountValue;
}

/// <summary>
/// Instantiate new object
/// </summary>
/// <returns>The new object</returns>
public static METPriceComponentContract construct()
{
    return new METPriceComponentContract();
}

/// <summary>
/// send PE component detail
/// </summary>
/// <param name = "_metPriceComponentDetailClassArray">PE component details</param>
/// <returns>returns PE component detail</returns>
[DataMemberAttribute("METPriceComponentDetailContract"),
DataCollection(Types::Class, classStr(METPriceComponentDetailContract)),
AifCollectionTypeAttribute('_metPriceComponentDetailClassArray', Types::Class, classStr(METPriceComponentDetailContract)),
AifCollectionTypeAttribute('return', Types::Class, classStr(METPriceComponentDetailContract))]
public List parmSendPEPriceComponetDetailClassArray(List _metPriceComponentDetailClassArray = priceComponentDetailArray)
{
    if (!prmIsDefault(_metPriceComponentDetailClassArray))
    {
        priceComponentDetailArray = _metPriceComponentDetailClassArray;
    }

    return priceComponentDetailArray;
}
